import{_ as o,o as a,c as r,a6 as i}from"./chunks/framework.QBF2cGGQ.js";const m=JSON.parse('{"title":"11 · 前端专有","description":"","frontmatter":{},"headers":[],"relativePath":"guide/11-frontend.md","filePath":"guide/11-frontend.md","lastUpdated":1793327470000}'),t={name:"guide/11-frontend.md"};function n(p,s,l,e,u,g){return a(),r("div",null,[...s[0]||(s[0]=[i('<h1 id="_11-·-前端专有" tabindex="-1">11 · 前端专有 <a class="header-anchor" href="#_11-·-前端专有" aria-label="Permalink to &quot;11 · 前端专有&quot;">​</a></h1><blockquote><p><strong>你的存量优势</strong> · 这一层不用&quot;学&quot;，是把你已有的能力翻译到 AI 场景。 翻译好了，你就是市场上稀缺的那类人。</p></blockquote><h2 id="为什么这是优势而不是劣势" tabindex="-1">为什么这是优势而不是劣势 <a class="header-anchor" href="#为什么这是优势而不是劣势" aria-label="Permalink to &quot;为什么这是优势而不是劣势&quot;">​</a></h2><p>很多人转 AI 会下意识觉得&quot;前端离模型太远&quot;。但真实情况是：AI 产品的体验瓶颈几乎全在交互层——等待怎么表达、流式怎么渲染、错误怎么兜住、引用怎么溯源。这些恰恰是后端工程师最不擅长的部分。</p><p>你去面试时，如果对方问&quot;你为什么觉得自己能做这个&quot;，最有力的回答不是&quot;我在学 RAG&quot;，而是&quot;我能把模型的不确定性做成用户敢用的界面，而这正好是现在大部分 AI 产品最烂的地方&quot;。</p><h2 id="流式渲染" tabindex="-1">流式渲染 <a class="header-anchor" href="#流式渲染" aria-label="Permalink to &quot;流式渲染&quot;">​</a></h2><ul><li><strong>流式文本渲染性能</strong> <span class="prio prio-must">必须</span> — 每来一个 token 就 setState 会卡死。用 buffer + requestAnimationFrame 批量刷新。</li><li><strong>Markdown 增量渲染</strong> <span class="prio prio-must">必须</span> — 不完整的 Markdown（比如代码块没闭合）会导致渲染抖动。需要容错解析。</li><li><strong>代码块流式高亮</strong> <span class="prio prio-imp">重要</span> — 高亮开销大，要节流或等代码块结束后再高亮。</li><li><strong>LaTeX / 表格渲染</strong> <span class="prio prio-imp">重要</span> — 流式过程中的半截公式与表格要有降级显示。</li><li><strong>生成中断 AbortController</strong> <span class="prio prio-must">必须</span> — 用户点&quot;停止&quot;要真正中断请求，并保留已生成内容。</li><li><strong>重新生成与编辑重发</strong> <span class="prio prio-must">必须</span> — 重新生成要能切换版本，编辑重发要截断后续消息。</li><li><strong>滚动跟随策略</strong> <span class="prio prio-imp">重要</span> — 用户上滑查看历史时不能强制拉回底部，这是最常被做错的细节。</li></ul><h2 id="会话-ui" tabindex="-1">会话 UI <a class="header-anchor" href="#会话-ui" aria-label="Permalink to &quot;会话 UI&quot;">​</a></h2><ul><li><strong>消息列表虚拟滚动</strong> <span class="prio prio-must">必须</span> — 长会话几百条消息，不虚拟化直接卡。</li><li><strong>多轮会话状态</strong> <span class="prio prio-must">必须</span> — 会话切换、草稿保存、未读标记。</li><li><strong>引用与溯源展示</strong> <span class="prio prio-must">必须</span> — 点引用能定位到原文片段，这是 RAG 产品的信任基础。</li><li><strong>工具调用过程可视化</strong> <span class="prio prio-must">必须</span> — &quot;正在搜索…&quot;&quot;正在读取文件…&quot;，让等待可解释。</li><li><strong>思考过程展示</strong> <span class="prio prio-imp">重要</span> — reasoning 内容折叠展示，兼顾透明度与简洁。</li><li><strong>错误态与降级</strong> <span class="prio prio-must">必须</span> — 模型超时、审核拦截、额度用尽，每种都要有明确文案与出路。</li><li><strong>空态与引导</strong> <span class="prio prio-must">必须</span> — AI 产品最大的流失点是&quot;不知道能问什么&quot;。用示例问题引导。</li><li><strong>生成中的可编辑性</strong> <span class="prio prio-imp">重要</span> — 边生成边让用户改，还是生成完再改？交互范式要提前定。</li><li><strong>多版本答案对比</strong> <span class="prio prio-opt">选学</span> — 重新生成的多个版本可横向对比，适合写作类场景。</li></ul><h2 id="输入与多模态" tabindex="-1">输入与多模态 <a class="header-anchor" href="#输入与多模态" aria-label="Permalink to &quot;输入与多模态&quot;">​</a></h2><ul><li><strong>附件上传与预览</strong> <span class="prio prio-must">必须</span> — 图片、PDF、表格、代码文件。上传后要能预览与删除。</li><li><strong>前端文件解析</strong> <span class="prio prio-imp">重要</span> — PDF.js 抽文本、图片压缩、超大文件分片。</li><li><strong>拖拽与粘贴</strong> <span class="prio prio-must">必须</span> — 粘贴截图直接上传，是高频刚需。</li><li><strong>语音输入 ASR</strong> <span class="prio prio-imp">重要</span> — 流式转写、静音检测、打断。</li><li><strong>TTS 播放与打断</strong> <span class="prio prio-imp">重要</span> — 边生成边播、用户说话时立即停。</li><li><strong>实时语音对话 WebRTC</strong> <span class="prio prio-opt">选学</span> — 端到端延迟要求 &lt; 800ms，架构与文本完全不同。</li><li><strong>图像理解结果展示</strong> <span class="prio prio-opt">选学</span> — 边界框、区域标注、多图对比。</li><li><strong>上传进度与失败重试</strong> <span class="prio prio-imp">重要</span> — 大文件上传必须有进度与断点续传。</li></ul><h2 id="交互范式" tabindex="-1">交互范式 <a class="header-anchor" href="#交互范式" aria-label="Permalink to &quot;交互范式&quot;">​</a></h2><ul><li><strong>从&quot;点击&quot;到&quot;对话 + 确认&quot;</strong> <span class="prio prio-must">必须</span> — AI 产品不是纯聊天框。最佳实践是&quot;对话负责意图，控件负责精确&quot;。</li><li><strong>Generative UI</strong> <span class="prio prio-imp">重要</span> — 模型输出组件描述，前端渲染成真实控件。前沿方向。</li><li><strong>结构化输出的表单化</strong> <span class="prio prio-must">必须</span> — 让模型填表比让它写文章更可靠，也更易校验。</li><li><strong>渐进式披露</strong> <span class="prio prio-imp">重要</span> — 先给结论再给细节，别一上来铺满屏幕。</li><li><strong>可访问性</strong> <span class="prio prio-imp">重要</span> — 动态内容要能被屏幕阅读器正确播报，aria-live 的节奏要控。</li><li><strong>快捷键与命令面板</strong> <span class="prio prio-opt">选学</span> — 重度用户效率的关键，也是产品成熟度标志。</li><li><strong>移动端适配</strong> <span class="prio prio-imp">重要</span> — 软键盘弹起、长文本滚动、横竖屏切换，在对话场景里都是坑。</li></ul><h2 id="一个具体的技术建议" tabindex="-1">一个具体的技术建议 <a class="header-anchor" href="#一个具体的技术建议" aria-label="Permalink to &quot;一个具体的技术建议&quot;">​</a></h2><p>如果你只做一件事来证明这块能力，就做一个&quot;流式渲染性能过关的对话界面&quot;：1000 条消息不卡、边生成边滚动不抖、代码块高亮不闪、断网能续、错误有出路。这件事后端做不了，而它是所有 AI 产品的地基。</p>',15)])])}const d=o(t,[["render",n]]);export{m as __pageData,d as default};
